from datetime import date

def overdue(inventory, today, limits):
    out = []
    for m in inventory:
        d = m['last_validated']
        if d is None:
            out.append(m['id'])
            continue
        months = (today.year - d.year) * 12 + today.month - d.month
        if months > limits[m['tier']]:
            out.append(m['id'])
    return sorted(out)
